// Discover stage — n8n Code node (Run Once for All Items).
// Input : { website_url } (webhook body). Output: one item per same-domain page URL.
// NOTE: the n8n JS Task Runner sandbox does NOT expose the global `URL` — all URL
// parsing/joining here is done with plain string ops. Only this.helpers.httpRequest
// is available for HTTP.

try {
  const helpers = this.helpers;
  const input = $input.first().json;
  const body = (input && input.body) ? input.body : (input || {});
  let website = String(body.website_url || (input && input.website_url) || '').trim();
  if (!website) { throw new Error('website_url is required'); }
  if (!/^https?:\/\//i.test(website)) website = 'https://' + website;

  function parseUrl(str) {
    const m = String(str).match(/^(https?:)\/\/([^\/:?#]+)(:\d+)?([^?#]*)/i);
    if (!m) return null;
    const host = m[2];
    return { protocol: m[1], host, port: m[3] || '', path: m[4] || '/', origin: m[1] + '//' + host + (m[3] || '') };
  }
  const startParsed = parseUrl(website);
  if (!startParsed) throw new Error('invalid website_url: ' + website);
  const startUrl = website;
  const origin = startParsed.origin;
  const baseDomain = startParsed.host.replace(/^www\./, '');
  const maxPages = parseInt(body.max_pages || 80, 10);
  const ua = body.user_agent || 'DentalRAGBot/1.0';

  function hostOf(url) { const p = parseUrl(url); return p ? p.host.replace(/^www\./, '') : null; }
  function sameDomain(url) { return hostOf(url) === baseDomain; }
  function resolveUrl(href) {
    href = String(href).trim();
    if (/^https?:\/\//i.test(href)) return href;
    if (/^\/\//.test(href)) return 'https:' + href;
    if (href.charAt(0) === '/') return origin + href;
    if (/^(mailto:|tel:|javascript:|#)/i.test(href)) return null;
    return origin + '/' + href.replace(/^\.?\//, '');
  }

  async function fetchText(url) {
    try {
      const res = await helpers.httpRequest({ url, method: 'GET', headers: { 'User-Agent': ua }, json: false });
      return typeof res === 'string' ? res : String(res);
    } catch (e) { return null; }
  }

  const found = new Set();
  const sitemaps = [];

  const robots = await fetchText(origin + '/robots.txt');
  if (robots) {
    for (const line of robots.split(/\r?\n/)) {
      const m = line.match(/^\s*sitemap:\s*(\S+)/i);
      if (m) sitemaps.push(m[1].trim());
    }
  }
  if (sitemaps.length === 0) sitemaps.push(origin + '/sitemap.xml');

  const seen = new Set();
  const queue = sitemaps.slice();
  let walked = 0;
  while (queue.length && walked < 25 && found.size < maxPages) {
    const sm = queue.shift();
    if (seen.has(sm)) continue;
    seen.add(sm); walked++;
    const xml = await fetchText(sm);
    if (!xml) continue;
    const locs = (xml.match(/<loc>\s*[^<\s]+\s*<\/loc>/gi) || []).map(function (t) {
      return t.replace(/<\/?loc>/gi, '').trim();
    });
    for (const loc of locs) {
      if (/\.xml(\?|$)/i.test(loc)) queue.push(loc);
      else if (sameDomain(loc)) found.add(loc.split('#')[0]);
      if (found.size >= maxPages) break;
    }
  }

  let discovery = 'sitemap';
  if (found.size === 0) {
    discovery = 'crawl';
    found.add(startUrl);
    const html = await fetchText(startUrl);
    if (html) {
      const hrefs = (html.match(/href=["'][^"']+["']/gi) || []).map(function (h) {
        return h.replace(/^href=["']/i, '').replace(/["']$/, '');
      });
      for (let href of hrefs) {
        const abs = resolveUrl(href);
        if (abs && sameDomain(abs) && !/\.(png|jpe?g|gif|svg|pdf|zip|css|js|ico|woff2?|mp4|webp)(\?|$)/i.test(abs)) {
          found.add(abs.split('#')[0]);
        }
        if (found.size >= maxPages) break;
      }
    }
  }

  const urls = Array.from(found).slice(0, maxPages);
  return urls.map(function (url) {
    return { json: { website_url: startUrl, origin, base_domain: baseDomain, discovery, url } };
  });
} catch (err) {
  return [{ json: { __discover_error: String((err && err.message) || err) } }];
}

// Fetch + clean stage — n8n Code node (Run Once for All Items).
// Input : one item per discovered URL { website_url, url, ... }
// Output: one item per page { website_url, url, status_code, page_type, title, char_count, url_hash, clean_text }
// Sandbox: only this.helpers.httpRequest; no URL/fetch globals. HTML cleaned via regex.

const helpers = this.helpers;
const items = $input.all();
const ua = 'DentalRAGBot/1.0';

function djb2(str) { // stable id for url_hash (no crypto in sandbox)
  let h = 5381;
  for (let i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) >>> 0;
  return 'h' + h.toString(16);
}
function decodeEntities(t) {
  return t.replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<')
          .replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;/gi, "'")
          .replace(/&apos;/gi, "'").replace(/&[a-z]+;/gi, ' ');
}
function cleanHtml(html) {
  if (!html) return '';
  let t = html;
  t = t.replace(/<script[\s\S]*?<\/script>/gi, ' ');
  t = t.replace(/<style[\s\S]*?<\/style>/gi, ' ');
  t = t.replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ');
  t = t.replace(/<!--[\s\S]*?-->/g, ' ');
  t = t.replace(/<\/(p|div|li|h[1-6]|br|tr|section|article)>/gi, '\n'); // keep some structure
  t = t.replace(/<[^>]+>/g, ' ');
  t = decodeEntities(t);
  t = t.replace(/[ \t\f\v]+/g, ' ').replace(/\s*\n\s*/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  return t;
}
function extractTitle(html) {
  const m = html && html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  return m ? decodeEntities(m[1].replace(/\s+/g, ' ')).trim() : '';
}
function classify(url) {
  const u = String(url).toLowerCase();
  if (/contact|location|direction|map/.test(u)) return 'contact';
  if (/faq/.test(u)) return 'faq';
  if (/price|pricing|cost|\bfee|payment|insurance|financ|afford/.test(u)) return 'pricing';
  if (/appointment|consult|request|book/.test(u)) return 'booking';
  if (/about|team|doctor|board-certified|staff|meet|\bbio/.test(u)) return 'about';
  if (/blog|news|article|post/.test(u)) return 'blog';
  if (/service|treatment|braces|invisalign|damon|itero|laser|retainer|aligner|orthodon/.test(u)) return 'service';
  if (/privacy|notice|policy|terms|hipaa/.test(u)) return 'policy';
  return 'general';
}

const out = [];
for (const it of items) {
  const website_url = it.json.website_url;
  const url = it.json.url;
  if (!url) continue;
  let html = null, status = 0;
  try {
    const res = await helpers.httpRequest({ url, method: 'GET', headers: { 'User-Agent': ua }, json: false });
    html = typeof res === 'string' ? res : String(res);
    status = 200;
  } catch (e) { status = 0; }
  const title = extractTitle(html || '');
  const clean_text = cleanHtml(html || '');
  out.push({
    json: {
      website_url, url, status_code: status,
      page_type: classify(url), title,
      char_count: clean_text.length,
      url_hash: djb2(url),
      clean_text,
    },
  });
}
return out;

// Prepare stage — n8n Code node (Run Once for All Items).
// Collapses all cleaned page items into ONE item carrying a JSON array, so the
// DB write is a single bulk insert with just two bound params (website_url + JSON).
const items = $input.all();
const website_url = items.length ? items[0].json.website_url : '';
const pages = items.map(function (it) {
  return {
    url: it.json.url,
    url_hash: it.json.url_hash,
    page_type: it.json.page_type,
    title: it.json.title || '',
    clean_text: it.json.clean_text || '',
    status_code: it.json.status_code || 0,
  };
});
return [{ json: { website_url, page_count: pages.length, pages_json: JSON.stringify(pages) } }];
